export function RfuMain2(): any {
  let retval: any = FALSE;
      if (!gRfu.isShuttingDown)
      {
          if (gRfu.parentChild == MODE_PARENT)
              retval = RfuMain2_Parent();
          RfuCheckErrorStatus();
      }
      return retval;
}

